-- BEGIN loadup-modules/loadup-modules-notification/loadup-modules-notification-core/src/main/resources/db/migration/framework/notification/V20261003000001__create_notification_inbox.sql
-- SHA-256: dfb468501b459042c311dc0c0d562eaa20c5680e6b448fc2723be7f075f22470
CREATE TABLE IF NOT EXISTS notification_inbox
(
    id           VARCHAR(64) PRIMARY KEY,
    recipient_id VARCHAR(64)   NOT NULL,
    sender_id    VARCHAR(64),
    category     VARCHAR(64)   NOT NULL,
    title        VARCHAR(200)  NOT NULL,
    body         VARCHAR(4000) NOT NULL,
    action_url   VARCHAR(500),
    request_key  VARCHAR(128),
    read_at      TIMESTAMP(6),
    archived_at  TIMESTAMP(6),
    created_at   TIMESTAMP(6)  NOT NULL,
    updated_at   TIMESTAMP(6)  NOT NULL,
    deleted      BOOLEAN       NOT NULL DEFAULT FALSE,
    CONSTRAINT uk_notification_delivery UNIQUE (recipient_id, request_key)
);
CREATE INDEX idx_notification_inbox ON notification_inbox (recipient_id, archived_at, created_at);
CREATE INDEX idx_notification_unread ON notification_inbox (recipient_id, archived_at, read_at);
-- END loadup-modules/loadup-modules-notification/loadup-modules-notification-core/src/main/resources/db/migration/framework/notification/V20261003000001__create_notification_inbox.sql

-- BEGIN loadup-modules/loadup-modules-transfer/loadup-modules-transfer-core/src/main/resources/db/migration/framework/transfer/V20261003000002__create_transfer_task.sql
-- SHA-256: 32778bf0e59f395894a0491c6562c0d6f1432c8f5b9b7a4a9bc2b0d573d31904
-- PostgreSQL initial schema.

CREATE TABLE transfer_task
(
    id              VARCHAR(64) COLLATE "C"        NOT NULL PRIMARY KEY,

    owner_id        VARCHAR(64) COLLATE "C"        NOT NULL,
    kind            VARCHAR(16) COLLATE "C"        NOT NULL,
    handler_key     VARCHAR(64) COLLATE "C"        NOT NULL,
    source_file_id  VARCHAR(64) COLLATE "C",
    result_file_id  VARCHAR(64) COLLATE "C",
    status          VARCHAR(16) COLLATE "C"        NOT NULL,
    processed_count BIGINT                         NOT NULL DEFAULT 0,
    total_count     BIGINT                         NOT NULL DEFAULT 0,
    error_message   VARCHAR(500) COLLATE "C",
    created_at      TIMESTAMP(6) WITHOUT TIME ZONE NOT NULL,
    started_at      TIMESTAMP(6) WITHOUT TIME ZONE,
    finished_at     TIMESTAMP(6) WITHOUT TIME ZONE,
    updated_at      TIMESTAMP(6) WITHOUT TIME ZONE NOT NULL,
    deleted         BOOLEAN                        NOT NULL DEFAULT FALSE
);

CREATE INDEX idx_transfer_owner ON transfer_task (owner_id, created_at);

CREATE INDEX idx_transfer_status ON transfer_task (status, created_at);

CREATE TABLE transfer_task_option
(
    task_id      VARCHAR(64) COLLATE "C"        NOT NULL,
    option_name  VARCHAR(64) COLLATE "C"        NOT NULL,
    option_value VARCHAR(1000) COLLATE "C"      NOT NULL,
    id           VARCHAR(64) COLLATE "C"        NOT NULL PRIMARY KEY,

    created_at   TIMESTAMP(6) WITHOUT TIME ZONE NOT NULL,
    updated_at   TIMESTAMP(6) WITHOUT TIME ZONE NOT NULL,
    deleted      BOOLEAN                        NOT NULL DEFAULT FALSE
);

CREATE UNIQUE INDEX uk_transfer_option ON transfer_task_option (task_id, option_name);
-- END loadup-modules/loadup-modules-transfer/loadup-modules-transfer-core/src/main/resources/db/migration/framework/transfer/V20261003000002__create_transfer_task.sql

-- BEGIN loadup-modules/loadup-modules-notification/loadup-modules-notification-core/src/main/resources/db/migration/framework/notification/V20261104100000__create_notification_requests.sql
-- SHA-256: 469e6dec1696076afb1bb6bd3fa5bf71ecb3aba6248332efb116c5599d2cb570
CREATE TABLE notification_request
(
    id VARCHAR(64) PRIMARY KEY,
    source VARCHAR(128) NOT NULL,
    request_key VARCHAR(128) NOT NULL,
    content_digest VARCHAR(64) NOT NULL,
    content_json TEXT NOT NULL,
    created_at TIMESTAMP(6) NOT NULL,
    updated_at TIMESTAMP(6) NOT NULL,
    deleted BOOLEAN NOT NULL DEFAULT FALSE,
    CONSTRAINT uk_notification_request UNIQUE (source, request_key)
);

CREATE TABLE notification_delivery
(
    id VARCHAR(64) PRIMARY KEY,
    notification_id VARCHAR(64) NOT NULL REFERENCES notification_request(id),
    recipient_id VARCHAR(64) NOT NULL,
    channel VARCHAR(16) NOT NULL CHECK (channel = 'IN_APP'),
    event_id VARCHAR(64) NOT NULL UNIQUE,
    status VARCHAR(16) NOT NULL CHECK (status IN ('PENDING', 'DELIVERED', 'EXPIRED')),
    created_at TIMESTAMP(6) NOT NULL,
    updated_at TIMESTAMP(6) NOT NULL,
    deleted BOOLEAN NOT NULL DEFAULT FALSE,
    CONSTRAINT uk_notification_target UNIQUE (notification_id, recipient_id, channel)
);
CREATE INDEX idx_notification_delivery_status ON notification_delivery (status, created_at);
-- END loadup-modules/loadup-modules-notification/loadup-modules-notification-core/src/main/resources/db/migration/framework/notification/V20261104100000__create_notification_requests.sql
